Command.ejemplo:
interface Command { execute(): void; undo(): void; }
class AddTextCommand implements Command {
  constructor(private doc: Doc, private text: string) {}
  execute() { this.doc.append(this.text); }
  undo() { this.doc.removeLast(this.text.length); }
}

Composite.ejemplo:
interface Node { size(): number; }
class FileLeaf implements Node { constructor(private bytes: number) {} size() { return this.bytes; } }
class Folder implements Node {
  constructor(private children: Node[] = []) {}
  size() { return this.children.reduce((acc, c) => acc + c.size(), 0); }
}

