Flyweight.ejemplo:
class GlyphFactory {
  private pool = new Map<string, Glyph>();
  get(char: string, font: string) {
    const key = `${char}:${font}`;
    return this.pool.get(key) ?? this.pool.set(key, new Glyph(char, font)).get(key)!;
  }
} // Posición (x, y) se pasa externamente al dibujar: glyph.draw(x, y);
